  let desc=d.querySelector('meta[name="description"]');if(!desc){desc=d.createElement('meta');desc.name='description';d.head.appendChild(desc)}desc.content='Han Sol Jung Research Group at KRICT: equipment-aware process systems engineering for carbon-neutral technologies, from equipment physics to plant decisions.';
  document.open();document.write('<!doctype html>'+d.documentElement.outerHTML);document.close();
